"""Português — sira (sira_001 … sira_150)."""

T = {
"sira_001": ("Em que cidade nasceu o Profeta Muhammad ﷺ?", ["Meca", "Medina", "Ta'if", "Jerusalém"], "O Profeta Muhammad ﷺ nasceu em Meca, no Hijaz."),
"sira_002": ("Como se chama o ano do nascimento do Profeta ﷺ, marcado pelo acontecimento do elefante?", ["O Ano do Elefante", "O Ano da Vitória", "O Ano do Camelo", "O Ano da Luz"], "O acontecimento do elefante, em que Allah protegeu a Ka'ba, é narrado na surata Al-Fil."),
"sira_003": ("Como se chamava a primeira esposa do Profeta ﷺ?", ["Khadija", "Aisha", "Hafsa", "Zaynab"], "Khadija bint Khuwaylid foi a primeira esposa do Profeta ﷺ e a primeira pessoa a crer na sua mensagem."),
"sira_004": ("Em que caverna recebeu o Profeta ﷺ a primeira revelação?", ["A caverna de Hira", "A caverna de Thawr", "A caverna dos Companheiros", "A caverna de Uhud"], "A primeira revelação ocorreu na caverna de Hira, no Jabal an-Nur, perto de Meca."),
"sira_005": ("Que anjo trouxe a revelação ao Profeta ﷺ?", ["Jibril (Gabriel)", "Mika'il (Miguel)", "Israfil", "Malik"], "O Alcorão menciona explicitamente que Jibril trouxe a revelação com a permissão de Allah."),
"sira_006": ("Como se chama a emigração do Profeta ﷺ e dos seus companheiros de Meca para Medina?", ["A Hégira", "Al-Isra", "Al-Mi'raj", "Al-Fath"], "A Hégira é a histórica emigração para Medina, ponto de partida do calendário islâmico."),
"sira_007": ("Para que cidade emigraram o Profeta ﷺ e Abu Bakr?", ["Medina", "Ta'if", "Damasco", "Jerusalém"], "O Profeta ﷺ e Abu Bakr emigraram de Meca para Medina (então chamada Yathrib)."),
"sira_008": ("O Alcorão descreve um companheiro como «o segundo de dois, quando estavam na caverna» durante a Hégira. Quem era?", ["Abu Bakr", "Umar", "Uthman", "Ali"], "O Alcorão refere-se a Abu Bakr, que acompanhou o Profeta ﷺ na caverna de Thawr durante a Hégira."),
"sira_009": ("Que batalha, mencionada no Alcorão, viu um pequeno exército muçulmano vencer uma força muito maior?", ["A batalha de Badr", "A batalha de Uhud", "A batalha da Trincheira", "A batalha de Hunayn"], "Em Badr, Allah deu a vitória a um pequeno grupo de crentes sobre um exército muito maior."),
"sira_010": ("Como se chama o regresso, em grande parte pacífico, do Profeta ﷺ e dos seus companheiros a Meca?", ["A conquista de Meca (Fath Makka)", "A batalha de Meca", "O cerco de Meca", "A queda de Meca"], "A conquista de Meca deu-se em grande parte pacificamente, sem derramamento de sangue generalizado."),
"sira_011": ("Como se chama o último sermão proferido pelo Profeta ﷺ perto do fim da sua vida?", ["O Sermão de Despedida", "O Sermão de Meca", "O Sermão da Caverna", "O Sermão de Badr"], "O Sermão de Despedida (Khutbat al-Wada') foi proferido durante a última peregrinação do Profeta ﷺ."),
"sira_012": ("Em que mês afirma o Alcorão que começou a sua revelação?", ["Ramadão", "Muharram", "Rajab", "Dhul-Hijja"], "O Alcorão afirma que o Ramadão é o mês em que foi revelado."),
"sira_013": ("Qual era a profissão do Profeta ﷺ antes de receber a revelação?", ["Comerciante", "Apenas pastor", "Ferreiro", "Escriba"], "O Profeta ﷺ trabalhou no comércio, um facto bem estabelecido da sua biografia."),
"sira_014": ("Que avô do Profeta ﷺ cuidou dele depois da morte da sua mãe?", ["Abdul Muttalib", "Abu Talib", "Abu Lahab", "Abu Sufyan"], "Abdul Muttalib cuidou do jovem Muhammad ﷺ depois da morte da sua mãe Amina."),
"sira_015": ("Que tio criou o Profeta ﷺ depois da morte do seu avô?", ["Abu Talib", "Al-Abbas", "Hamza", "Abu Lahab"], "Abu Talib encarregou-se de criar o sobrinho depois da morte de Abdul Muttalib."),
"sira_016": ("Como se chama a viagem noturna do Profeta ﷺ de Meca a Jerusalém, mencionada no Alcorão?", ["Al-Isra", "A Hégira", "Al-Fath", "Al-Ghazwa"], "A surata Al-Isra começa por descrever esta viagem noturna milagrosa."),
"sira_017": ("Qual das filhas do Profeta ﷺ casou com Ali ibn Abi Talib?", ["Fátima", "Zaynab", "Ruqayya", "Umm Kulthum"], "Fátima, filha do Profeta ﷺ e de Khadija, casou com Ali ibn Abi Talib, um facto amplamente estabelecido."),
"sira_018": ("Que mês marca o início do ano do calendário islâmico, em referência à Hégira?", ["Muharram", "Ramadão", "Shawwal", "Dhul-Qa'da"], "O calendário islâmico começa com o mês de Muharram, tomando como referência o ano da Hégira."),
"sira_019": ("Quem foi o primeiro muezim do islão, escolhido pelo Profeta ﷺ para chamar à oração?", ["Bilal ibn Rabah", "Abu Bakr", "Umar ibn al-Khattab", "Salman al-Farisi"], "Bilal, com a sua bela voz, foi escolhido como primeiro muezim do islão."),
"sira_020": ("Qual foi a primeira mesquita fundada pelo Profeta ﷺ ao chegar perto de Medina?", ["A mesquita de Quba", "A mesquita Al-Haram", "A mesquita Al-Aqsa", "A mesquita das duas qiblas"], "Ao chegar a Quba, às portas de Medina, o Profeta ﷺ fundou ali a primeira mesquita."),
"sira_021": ("Como se chamava a mãe do Profeta ﷺ?", ["Amina", "Khadija", "Halima", "Fátima"], "Amina bint Wahb foi a mãe do Profeta ﷺ; Halima foi a sua ama de leite."),
"sira_022": ("Como se chamava o pai do Profeta ﷺ, falecido antes do seu nascimento?", ["Abdullah", "Abu Talib", "Abd al-Muttalib", "Hamza"], "Abdullah, filho de Abd al-Muttalib, morreu antes de nascer o seu filho Muhammad ﷺ."),
"sira_023": ("Que alcunha deram os mequenses ao Profeta ﷺ antes da revelação, pela sua honestidade?", ["Al-Amin (o digno de confiança)", "Al-Faruq", "As-Siddiq", "Sayf Allah"], "Já antes da revelação lhe chamavam al-Amin: as pessoas confiavam-lhe os seus bens."),
"sira_024": ("Em que ano da Hégira ocorreu a conquista de Meca?", ["Ano 8", "Ano 2", "Ano 5", "Ano 10"], "No ano 8 da Hégira o Profeta ﷺ entrou em Meca quase sem combate e perdoou o seu povo."),
"sira_025": ("Em que ano da Hégira fez o Profeta ﷺ a sua Peregrinação de Despedida?", ["Ano 10", "Ano 6", "Ano 8", "Ano 12"], "A Peregrinação de Despedida ocorreu no ano 10; o Profeta ﷺ proferiu ali o seu último sermão."),
"sira_026": ("Quantas filhas teve o Profeta ﷺ?", ["4", "1", "2", "7"], "Zaynab, Ruqayya, Umm Kulthum e Fátima: as quatro filhas do Profeta ﷺ."),
"sira_027": ("Como se chamam os habitantes de Medina que acolheram e ajudaram os muçulmanos emigrados?", ["Os Ansar (os Auxiliares)", "Os Muhajirun", "Os Quraysh", "Os Tabi'un"], "Os Ansar, «os Auxiliares», partilharam as suas casas e bens com os irmãos emigrados."),
"sira_028": ("Como se chamam os muçulmanos que deixaram Meca para emigrar para Medina?", ["Os Muhajirun (os Emigrados)", "Os Ansar", "Os Hunafa'", "Os Ghuzat"], "Os Muhajirun deixaram casas e bens em Meca para preservar a sua fé."),
"sira_029": ("Em que mês ocorreu a batalha de Badr?", ["Ramadão", "Muharram", "Dhul-Hijja", "Rajab"], "A batalha de Badr ocorreu no Ramadão do ano 2 da Hégira."),
"sira_030": ("Antes de a qibla ser fixada para a Ka'ba, para que cidade rezavam os muçulmanos?", ["Jerusalém (Bayt al-Maqdis)", "Medina", "Ta'if", "Damasco"], "Os muçulmanos rezaram primeiro para Bayt al-Maqdis; depois Allah ordenou que se voltassem para a Mesquita Sagrada (Alcorão 2:142-144)."),
"sira_031": ("A que tribo pertencia o Profeta Muhammad ﷺ?", ["Quraysh", "Os Aws", "Os Khazraj", "Thaqif"], "Uma surata inteira tem o nome da sua tribo: Quraysh."),
"sira_032": ("De que clã de Quraysh vinha o Profeta ﷺ?", ["Banu Hashim", "Banu Umayya", "Banu Makhzum", "Banu Tamim"], "O Profeta ﷺ pertencia aos Banu Hashim, o clã do seu bisavô Hashim."),
"sira_033": ("Como se chamava a ama de leite que amamentou o Profeta ﷺ no deserto?", ["Halima as-Sa'diyya", "Amina", "Khadija", "Fátima"], "Segundo o costume mequense, a criança foi confiada a uma ama beduína: Halima as-Sa'diyya."),
"sira_034": ("Que tio do Profeta ﷺ, herói de Badr, caiu mártir em Uhud?", ["Hamza", "Abu Talib", "Al-Abbas", "Abu Lahab"], "Hamza ibn Abd al-Muttalib combateu em Badr e morreu na batalha de Uhud."),
"sira_035": ("Que primo do Profeta ﷺ, criado na sua casa, se tornou o quarto califa?", ["Ali ibn Abi Talib", "Ja'far", "Aqil", "Al-Abbas"], "Ali, filho de Abu Talib, cresceu com o Profeta ﷺ e foi o quarto califa bem guiado."),
"sira_036": ("Quem foi o primeiro califa depois da morte do Profeta ﷺ?", ["Abu Bakr", "Umar", "Uthman", "Ali"], "Abu Bakr as-Siddiq foi escolhido como primeiro califa."),
"sira_037": ("Que título tem Abu Bakr, por ter acreditado no Profeta ﷺ sem hesitar?", ["As-Siddiq (o Veraz)", "Al-Faruq", "Dhun-Nurayn", "Sayf Allah"], "Abu Bakr é chamado as-Siddiq, aquele que afirma e crê na verdade."),
"sira_038": ("Que título tem Umar ibn al-Khattab?", ["Al-Faruq (o que distingue a verdade da falsidade)", "As-Siddiq", "Dhun-Nurayn", "Al-Amin"], "Umar é chamado al-Faruq, aquele que separa a verdade da falsidade."),
"sira_039": ("Porque é Uthman ibn Affan chamado «Dhun-Nurayn», o das duas luzes?", ["Casou com duas filhas do Profeta ﷺ, uma após a outra", "Levava duas lâmpadas", "Memorizou o Alcorão duas vezes", "Fez duas hégiras"], "Uthman casou com Ruqayya e, depois da morte dela, com Umm Kulthum, ambas filhas do Profeta ﷺ."),
"sira_040": ("Em que ordem se sucederam os quatro califas bem guiados?", ["Abu Bakr, Umar, Uthman, Ali", "Ali, Umar, Abu Bakr, Uthman", "Umar, Abu Bakr, Ali, Uthman", "Abu Bakr, Ali, Umar, Uthman"], "Abu Bakr, depois Umar, depois Uthman, depois Ali."),
"sira_041": ("Quem foi a primeira pessoa a crer na mensagem do Profeta ﷺ?", ["Khadija, a sua esposa", "Abu Bakr", "Ali", "Bilal"], "Khadija acreditou nele desde a primeira revelação e apoiou-o."),
"sira_042": ("Quem comprou Bilal para o libertar das torturas do seu senhor?", ["Abu Bakr", "Umar", "Hamza", "Uthman"], "Abu Bakr comprou Bilal e libertou-o."),
"sira_043": ("Quem foi a primeira mártir do islão, morta em Meca pela sua fé?", ["Sumayya, mãe de Ammar", "Asma", "Umm Salama", "Safiyya"], "Sumayya bint Khayyat, mãe de Ammar ibn Yasir, foi morta por Abu Jahl."),
"sira_044": ("Para que terra se deu a primeira emigração de muçulmanos perseguidos em Meca?", ["Abissínia (Etiópia)", "Pérsia", "Iémen", "Egito"], "Os primeiros emigrantes foram para a Abissínia, junto de um rei justo."),
"sira_045": ("Como se chamava o rei da Abissínia que protegeu os muçulmanos e por quem o Profeta ﷺ rezou a oração fúnebre à distância?", ["An-Najashi (o Negus)", "Heráclio", "Cosroes", "Al-Muqawqis"], "O Profeta ﷺ anunciou a morte do Negus no próprio dia e rezou por ele com os companheiros."),
"sira_046": ("Que companheiro falou perante o Negus para explicar o islão?", ["Ja'far ibn Abi Talib", "Uthman", "Bilal", "Mus'ab ibn Umayr"], "Ja'far explicou ao rei o que o Profeta ﷺ ensinava e recitou-lhe versículos da surata Maryam."),
"sira_047": ("Que tio do Profeta ﷺ é condenado pelo nome no Alcorão?", ["Abu Lahab", "Abu Talib", "Al-Abbas", "Hamza"], "«Pereçam as mãos de Abu Lahab, e pereça ele!»"),
"sira_048": ("Como se chama o ano em que o Profeta ﷺ perdeu a esposa Khadija e o tio Abu Talib?", ["O Ano da Tristeza", "O Ano do Elefante", "O Ano das Delegações", "O Ano da Fome"], "Os dois grandes apoios do Profeta ﷺ morreram no mesmo ano, conhecido como o Ano da Tristeza."),
"sira_049": ("Em que cidade foi o Profeta ﷺ expulso e ferido depois de chamar ao islão, antes de recusar que o anjo das montanhas esmagasse o seu povo?", ["At-Ta'if", "Medina", "Khaybar", "Tabuk"], "Rejeitado em Ta'if, recusou destruir o seu povo, esperando que os seus descendentes adorassem Allah."),
"sira_050": ("Durante a Viagem Noturna e a Ascensão (Isra e Mi'raj), que obrigação foi prescrita aos muçulmanos?", ["As cinco orações diárias", "O jejum do Ramadão", "O zakat", "A peregrinação"], "As orações foram prescritas nessa noite, reduzidas de cinquenta para cinco, com a recompensa de cinquenta."),
"sira_051": ("Que árvore, no limite extremo, viu o Profeta ﷺ durante a Ascensão, segundo a surata An-Najm?", ["Sidrat al-Muntaha", "A oliveira abençoada", "A palmeira de Maryam", "A árvore de Tuba"], "«Junto a Sidrat al-Muntaha», o lódão do limite extremo."),
"sira_052": ("Como se chamam os juramentos de fidelidade que gente de Yathrib prestou ao Profeta ﷺ antes da Hégira?", ["Os juramentos de Al-Aqaba", "O pacto de Hudaybiyya", "O juramento da árvore", "A Constituição de Medina"], "Gente de Yathrib jurou fidelidade ao Profeta ﷺ em Al-Aqaba, perto de Mina, antes da Hégira."),
"sira_053": ("Que companheiro enviou o Profeta ﷺ a Yathrib, antes da Hégira, para ensinar o islão?", ["Mus'ab ibn Umayr", "Bilal", "Abu Hurayra", "Khalid ibn al-Walid"], "Mus'ab ibn Umayr foi o primeiro enviado a Yathrib, ensinando o Alcorão aos novos muçulmanos."),
"sira_054": ("Quem dormiu na cama do Profeta ﷺ na noite em que ele partiu para a Hégira?", ["Ali ibn Abi Talib", "Abu Bakr", "Zayd ibn Haritha", "Bilal"], "Ali ocupou o seu lugar na cama para enganar os vigilantes, e depois devolveu os depósitos aos mequenses."),
"sira_055": ("Em que caverna se esconderam o Profeta ﷺ e Abu Bakr durante a Hégira?", ["A caverna de Thawr", "A caverna de Hira", "A caverna de Uhud", "A caverna de Ta'if"], "Esconderam-se três dias na caverna de Thawr, a sul de Meca."),
"sira_056": ("Que filha de Abu Bakr levou provisões à caverna e foi apelidada «a dos dois cintos»?", ["Asma", "Aisha", "Umm Kulthum", "Umm Ruman"], "Asma partiu o seu cinto em dois para atar as provisões: daí «Dhat an-Nitaqayn»."),
"sira_057": ("O que aconteceu a Suraqa, que perseguiu o Profeta ﷺ durante a Hégira?", ["O seu cavalo afundou-se na terra e ele pediu segurança", "Alcançou o Profeta ﷺ", "Perdeu-se no deserto", "Adoeceu"], "As patas do seu cavalo afundaram-se na terra; Suraqa pediu salvo-conduto e partiu sem fazer mal."),
"sira_058": ("Qual era o antigo nome de Medina, mencionado no Alcorão?", ["Yathrib", "Tayba", "Khaybar", "Bakka"], "«Ó gente de Yathrib…», diz o Alcorão, recordando a batalha dos coligados."),
"sira_059": ("Como se chamava a camela do Profeta ﷺ, que se ajoelhou em Hudaybiyya?", ["Al-Qaswa", "Al-Buraq", "Ad-Duldul", "Al-Adba"], "Em Hudaybiyya, Al-Qaswa ajoelhou-se; o Profeta ﷺ disse: «Quem deteve o elefante deteve-a»."),
"sira_060": ("O que estabeleceu o Profeta ﷺ entre os Muhajirun e os Ansar ao chegar a Medina?", ["Uma irmandade, dois a dois", "Um imposto", "Um exército", "Um mercado"], "Irmanou os emigrados com os auxiliares, cada Muhajir com um irmão dos Ansar."),
"sira_061": ("Como se chama o documento com que o Profeta ﷺ organizou as relações entre as comunidades de Medina?", ["A Sahifa (Constituição) de Medina", "O tratado de Hudaybiyya", "O pacto de Ta'if", "A carta de Quba"], "A Sahifa fixou os direitos e deveres dos muçulmanos e das outras tribos de Medina."),
"sira_062": ("Como se chamavam os companheiros pobres que viviam na mesquita do Profeta ﷺ?", ["Ahl as-Suffa (a gente do banco)", "Os Muhajirun", "Os Ansar", "Os Hawariyyun"], "Abu Hurayra conta que esteve entre a gente da Suffa, alimentada pelo Profeta ﷺ."),
"sira_063": ("Quantos anos depois da Hégira ocorreu a batalha de Badr?", ["Dois", "Cinco", "Oito", "Dez"], "Badr foi travada no ano 2 da Hégira, durante o Ramadão."),
"sira_064": ("Quantos anjos prometeu Allah enviar como reforço aos crentes em Badr?", ["Mil", "Cem", "Dez", "Cem mil"], "«Reforçar-vos-ei com mil anjos, uns após os outros.»"),
"sira_065": ("Em Uhud, que erro dos arqueiros mudou o rumo da batalha?", ["Abandonaram a colina apesar da ordem do Profeta ﷺ", "Dispararam cedo demais", "Adormeceram", "Mudaram de lado"], "O Profeta ﷺ tinha ordenado aos arqueiros que não se movessem; a maioria desceu pelo espólio e a cavalaria inimiga contornou-os."),
"sira_066": ("Perto de que cidade fica o monte Uhud?", ["Medina", "Meca", "Ta'if", "Jerusalém"], "O monte Uhud fica a norte de Medina; a batalha ocorreu no seu sopé."),
"sira_067": ("Que companheiro sugeriu cavar uma trincheira para defender Medina dos coligados?", ["Salman al-Farisi", "Bilal", "Abu Dharr", "Suhayb"], "Salman, o Persa, sugeriu a trincheira, uma tática conhecida na Pérsia."),
"sira_068": ("Por que outro nome é conhecida a batalha da Trincheira, segundo a surata que fala dela?", ["A batalha dos Coligados (Al-Ahzab)", "A batalha de Badr", "A batalha de Hunayn", "A batalha de Mu'ta"], "A surata Al-Ahzab recorda os exércitos aliados que cercaram Medina e o vento enviado contra eles."),
"sira_069": ("Como se chama o juramento prestado debaixo de uma árvore em Hudaybiyya, com o qual Allah diz estar satisfeito?", ["Bay'at ar-Ridwan", "Bay'at al-Aqaba", "Bay'at an-Nisa", "Bay'at al-Fath"], "«Allah ficou satisfeito com os crentes quando te juraram fidelidade debaixo da árvore.»"),
"sira_070": ("Que surata começa com «Demos-te uma vitória clara», revelada depois do tratado de Hudaybiyya?", ["Al-Fath", "An-Nasr", "Al-Anfal", "At-Tawba"], "«Na verdade, demos-te uma vitória clara»: a surata Al-Fath."),
"sira_071": ("Em que ano da Hégira foi concluído o tratado de Hudaybiyya?", ["Ano 6", "Ano 2", "Ano 8", "Ano 10"], "O tratado de Hudaybiyya foi concluído no ano 6 entre os muçulmanos e os Quraysh."),
"sira_072": ("Que imperador bizantino recebeu a carta do Profeta ﷺ a convidá-lo ao islão e interrogou Abu Sufyan sobre ele?", ["Heráclio", "Nero", "Constantino", "Justiniano"], "Heráclio interrogou Abu Sufyan sobre o Profeta ﷺ depois de receber a sua carta."),
"sira_073": ("A quem entregou o Profeta ﷺ o estandarte em Khaybar, depois de dizer: «Amanhã dá-lo-ei a um homem que Allah e o Seu Mensageiro amam»?", ["Ali ibn Abi Talib", "Abu Bakr", "Umar", "Sa'd ibn Abi Waqqas"], "Chamou Ali, que tinha os olhos doentes; aplicou-lhe a sua saliva, curou-o e deu-lhe o estandarte."),
"sira_074": ("Que três comandantes caíram um após o outro na batalha de Mu'ta?", ["Zayd ibn Haritha, Ja'far ibn Abi Talib e Abdullah ibn Rawaha", "Hamza, Mus'ab e Sa'd", "Abu Bakr, Umar e Uthman", "Bilal, Salman e Suhayb"], "O Profeta ﷺ anunciou em Medina: «Zayd tomou o estandarte e caiu, depois Ja'far, depois Ibn Rawaha… depois tomou-o uma espada de Allah»."),
"sira_075": ("A que companheiro chamou o Profeta ﷺ «uma espada entre as espadas de Allah»?", ["Khalid ibn al-Walid", "Ali", "Hamza", "Abu Ubayda"], "Em Mu'ta, «uma espada entre as espadas de Allah», Khalid ibn al-Walid, tomou o estandarte e salvou o exército."),
"sira_076": ("O que fez o Profeta ﷺ aos ídolos em redor da Ka'ba na conquista de Meca?", ["Derrubou-os recitando «Veio a verdade e desvaneceu-se a falsidade»", "Vendeu-os", "Levou-os para Medina", "Deixou-os no lugar"], "Bateu nos ídolos com o seu bastão dizendo: «Veio a verdade e desvaneceu-se a falsidade»."),
"sira_077": ("Quem fez a chamada à oração do alto da Ka'ba no dia da conquista de Meca?", ["Bilal", "Abu Bakr", "Ali", "Umar"], "O Profeta ﷺ ordenou a Bilal que subisse à Ka'ba e chamasse à oração."),
"sira_078": ("O que disse o Profeta ﷺ aos mequenses vencidos que o tinham perseguido, no dia da conquista?", ["«Ide, sois livres»", "«Sereis julgados amanhã»", "«Deixai a cidade»", "«Pagai um resgate»"], "Perdoou-lhes: «Ide, sois livres»."),
"sira_079": ("Em que batalha, nomeada no Alcorão, foram os muçulmanos surpreendidos no início apesar do seu grande número?", ["Hunayn", "Badr", "Uhud", "Khaybar"], "«No dia de Hunayn, o vosso grande número agradou-vos, mas de nada vos serviu.»"),
"sira_080": ("Que companheiro, que ficou para trás na expedição de Tabuk, confessou honestamente e foi perdoado por uma revelação?", ["Ka'b ibn Malik", "Abu Dharr", "Anas ibn Malik", "Abu Hurayra"], "Ka'b ibn Malik disse a verdade, suportou cinquenta dias de isolamento e depois Allah revelou o seu perdão (9:118)."),
"sira_081": ("Como se chama o ano 9 da Hégira, em que muitas tribos vieram a Medina abraçar o islão?", ["O Ano das Delegações", "O Ano da Tristeza", "O Ano do Elefante", "O Ano da Seca"], "Depois da conquista de Meca, as delegações das tribos árabes afluíram a Medina."),
"sira_082": ("Onde proferiu o Profeta ﷺ o seu Sermão de Despedida?", ["Em Arafat", "Em Medina", "No monte Uhud", "Em Ta'if"], "O Sermão de Despedida foi proferido em Arafat, durante a Peregrinação de Despedida."),
"sira_083": ("Que versículo, revelado durante a Peregrinação de Despedida, anuncia que a religião foi completada?", ["«Hoje completei para vós a vossa religião»", "«Lê, em nome do teu Senhor»", "«Quando chegar o auxílio de Allah»", "«Diz: Ele é Allah, Único»"], "«Hoje completei para vós a vossa religião e cumpri sobre vós a Minha graça.»"),
"sira_084": ("Em que cidade morreu e foi sepultado o Profeta ﷺ?", ["Medina", "Meca", "Jerusalém", "Ta'if"], "Morreu em Medina no ano 11 da Hégira e foi ali sepultado."),
"sira_085": ("No quarto de que esposa foi sepultado o Profeta ﷺ?", ["De Aisha", "De Khadija", "De Hafsa", "De Umm Salama"], "Foi sepultado onde morreu, no quarto de Aisha, hoje dentro da Mesquita do Profeta."),
"sira_086": ("Quem declarou, à morte do Profeta ﷺ: «Quem adorava Muhammad, Muhammad morreu; quem adora Allah, Allah é o Vivente»?", ["Abu Bakr", "Umar", "Ali", "Bilal"], "Abu Bakr acalmou os companheiros e recitou: «Muhammad não é senão um mensageiro…» (3:144)."),
"sira_087": ("Como se chamavam os dois netos do Profeta ﷺ, filhos de Fátima e Ali?", ["Al-Hasan e Al-Husayn", "Ibrahim e Isma'il", "Zayd e Usama", "Ja'far e Aqil"], "Al-Hasan e Al-Husayn, que o Profeta ﷺ amava ternamente."),
"sira_088": ("Que esposa do Profeta ﷺ era filha de Abu Bakr?", ["Aisha", "Hafsa", "Zaynab", "Sawda"], "Aisha, filha de Abu Bakr, transmitiu um grande número de hadiths."),
"sira_089": ("Que esposa do Profeta ﷺ era filha de Umar ibn al-Khattab?", ["Hafsa", "Aisha", "Umm Habiba", "Maymuna"], "Hafsa bint Umar; a primeira cópia compilada do Alcorão ficou guardada com ela."),
"sira_090": ("Que companheiro narrou o maior número de hadiths do Profeta ﷺ?", ["Abu Hurayra", "Anas ibn Malik", "Abdullah ibn Umar", "Jabir"], "Abu Hurayra, que acompanhou de perto o Profeta ﷺ, é o companheiro que mais hadiths narrou."),
"sira_091": ("Que jovem companheiro serviu o Profeta ﷺ durante dez anos sem nunca ouvir uma repreensão?", ["Anas ibn Malik", "Usama ibn Zayd", "Ibn Abbas", "Zayd ibn Thabit"], "Anas disse: «Servi o Profeta ﷺ dez anos; nunca me disse “uf”, nem “porque fizeste isso?”»."),
"sira_092": ("Por que jovem primo rezou o Profeta ﷺ: «Ó Allah, ensina-lhe o Livro»?", ["Abdullah ibn Abbas", "Ali", "Ja'far", "Usama"], "O Profeta ﷺ abraçou Ibn Abbas e disse: «Ó Allah, ensina-lhe o Livro»."),
"sira_093": ("Que companheiro enviou o Profeta ﷺ ao Iémen, dizendo-lhe que chamasse primeiro à unicidade de Allah?", ["Mu'adh ibn Jabal", "Bilal", "Abu Musa sozinho", "Zayd ibn Haritha"], "«Vais ter com um povo do Livro: chama-os primeiro a testemunhar que não há deus senão Allah…»"),
"sira_094": ("A que companheiro chamou o Profeta ﷺ «o homem de confiança (amin) desta comunidade»?", ["Abu Ubayda ibn al-Jarrah", "Abu Bakr", "Uthman", "Khalid"], "«Cada comunidade tem um homem de confiança, e o desta comunidade é Abu Ubayda ibn al-Jarrah.»"),
"sira_095": ("Que companheiro, escriba da revelação, foi encarregado por Abu Bakr de compilar o Alcorão?", ["Zayd ibn Thabit", "Abu Hurayra", "Anas ibn Malik", "Salman"], "Depois da batalha de al-Yamama, Abu Bakr encarregou Zayd ibn Thabit de compilar o Alcorão."),
"sira_096": ("Sob que califa foram enviadas cópias oficiais do Alcorão às províncias?", ["Uthman ibn Affan", "Abu Bakr", "Umar", "Ali"], "Uthman mandou copiar o mushaf e enviou um exemplar a cada província."),
"sira_097": ("De que terra vinha o companheiro Salman, chamado «al-Farisi»?", ["Pérsia", "Abissínia", "Bizâncio", "Iémen"], "Salman al-Farisi, «o Persa», veio da Pérsia em busca da verdade."),
"sira_098": ("Que companheiro, vindo das terras bizantinas, é chamado «ar-Rumi»?", ["Suhayb", "Bilal", "Salman", "Abu Dharr"], "Suhayb ar-Rumi cresceu entre os bizantinos antes de abraçar o islão em Meca."),
"sira_099": ("Como se chama a mesquita do Profeta ﷺ em Medina?", ["Al-Masjid an-Nabawi", "Al-Masjid al-Haram", "Al-Masjid al-Aqsa", "Masjid Quba"], "A mesquita que fundou em Medina chama-se a Mesquita do Profeta, al-Masjid an-Nabawi."),
"sira_100": ("Quantas vezes aparece o nome «Muhammad» no Alcorão?", ["Quatro", "Uma", "Doze", "Cem"], "Nos versículos 3:144, 33:40, 47:2 e 48:29; o nome «Ahmad» aparece em 61:6."),
"sira_101": ("Como descreve o Alcorão o Profeta ﷺ para os crentes, no versículo 33:21?", ["Um excelente exemplo", "Um juiz severo", "Um rei", "Um poeta"], "«Na verdade, tendes no Mensageiro de Allah um excelente exemplo.»"),
"sira_102": ("Qual era a kunya (alcunha paterna) do Profeta ﷺ?", ["Abu al-Qasim", "Abu Bakr", "Abu Abdullah", "Abu Talib"], "Chamavam-lhe Abu al-Qasim, pelo seu filho mais velho Al-Qasim."),
"sira_103": ("Como se chamava o filho do Profeta ﷺ nascido em Medina, que morreu muito pequeno?", ["Ibrahim", "Al-Qasim", "Abdullah", "Al-Hasan"], "Ibrahim, nascido em Medina, morreu bebé; o Profeta ﷺ chorou e disse que o coração se entristece sem dizer o que desagrada a Allah."),
"sira_104": ("Para quem conduziu o Profeta ﷺ uma caravana comercial à Síria antes da revelação?", ["Khadija", "Abu Bakr", "Abu Sufyan", "Al-Abbas"], "Khadija, rica comerciante, confiou-lhe a sua caravana para a Síria e depois propôs-lhe casamento."),
"sira_105": ("Como resolveu o jovem Muhammad ﷺ a disputa dos clãs sobre a recolocação da Pedra Negra?", ["Pô-la sobre um pano que cada clã levantou, e depois colocou-a ele mesmo", "Levou-a sozinho", "Tirou à sorte", "Confiou-a a Abu Bakr"], "Estendeu um manto, pôs a Pedra em cima, fez os chefes de clã levantarem juntos o pano e colocou-a com a própria mão."),
"sira_106": ("Com que idade recebeu o Profeta ﷺ a primeira revelação?", ["Quarenta anos", "Vinte e cinco", "Cinquenta", "Sessenta"], "A revelação começou quando tinha quarenta anos, na caverna de Hira."),
"sira_107": ("A que primo de Khadija, conhecedor das Escrituras, foi levado o Profeta ﷺ depois da primeira revelação?", ["Waraqa ibn Nawfal", "Abu Talib", "Abu Lahab", "Al-Walid"], "Waraqa disse: «É o Namus (o anjo) que Allah enviou a Musa»."),
"sira_108": ("A que colina subiu o Profeta ﷺ para chamar publicamente os Quraysh, depois do versículo «Avisa os teus parentes mais próximos»?", ["As-Safa", "Uhud", "Arafat", "Hira"], "Subiu a as-Safa, chamou os clãs de Quraysh e avisou-os de um castigo severo."),
"sira_109": ("Que califa estabeleceu o calendário muçulmano a partir do ano da Hégira?", ["Umar ibn al-Khattab", "Abu Bakr", "Uthman", "Ali"], "Sob Umar, a Hégira foi escolhida como ponto de partida do calendário."),
"sira_110": ("Quantos anos viveu o Profeta ﷺ em Medina depois da Hégira?", ["Dez", "Três", "Vinte", "Treze"], "Viveu dez anos em Medina, desde a Hégira até à sua morte no ano 11."),
"sira_111": ("Durante quantos anos pregou o Profeta ﷺ em Meca antes da Hégira?", ["Treze", "Três", "Dez", "Vinte e três"], "Treze anos em Meca e depois dez em Medina: vinte e três anos de missão."),
"sira_112": ("Que companheiro poeta defendeu o Profeta ﷺ com os seus versos, e para quem ele pediu o apoio de Jibril?", ["Hassan ibn Thabit", "Ka'b ibn Malik", "Abdullah ibn Rawaha", "Labid"], "O Profeta ﷺ disse a Hassan: «Responde-lhes, e Jibril está contigo»."),
"sira_113": ("De que companheiro disse o Profeta ﷺ que lhe fora dada «uma das flautas da família de Dawud» pela sua bela recitação?", ["Abu Musa al-Ash'ari", "Bilal", "Ubayy ibn Ka'b", "Ibn Mas'ud"], "Ao ouvi-lo recitar, o Profeta ﷺ disse que a Abu Musa fora dada uma das flautas da família de Dawud."),
"sira_114": ("O Profeta ﷺ recomendou aprender o Alcorão com quatro companheiros. Qual destes era um deles?", ["Abdullah ibn Mas'ud", "Abu Hurayra", "Anas ibn Malik", "Khalid ibn al-Walid"], "«Aprendei o Alcorão com quatro: Ibn Mas'ud, Salim, Mu'adh ibn Jabal e Ubayy ibn Ka'b.»"),
"sira_115": ("Em que batalha foi o Profeta ﷺ ferido no rosto e perdeu um dente?", ["Uhud", "Badr", "Hunayn", "Khaybar"], "Em Uhud, partiu-se-lhe um dente e foi ferido no rosto."),
"sira_116": ("A que companheiro, arqueiro em Uhud, disse o Profeta ﷺ: «Dispara! Que o meu pai e a minha mãe sejam o teu resgate»?", ["Sa'd ibn Abi Waqqas", "Talha", "Az-Zubayr", "Ali"], "O Profeta ﷺ entregou-lhe flechas dizendo: «Dispara, que o meu pai e a minha mãe sejam sacrificados por ti»."),
"sira_117": ("Que caravana saíram os muçulmanos para intercetar, o que levou à batalha de Badr?", ["A de Abu Sufyan, que voltava da Síria", "A do Negus", "A dos persas", "A de Ta'if"], "A caravana de Quraysh conduzida por Abu Sufyan escapou, mas o exército mequense chegou a Badr."),
"sira_118": ("Quando abraçou o islão o chefe mequense Abu Sufyan?", ["Na conquista de Meca", "Antes da Hégira", "Em Badr", "Depois da morte do Profeta ﷺ"], "Abu Sufyan converteu-se na véspera da entrada do Profeta ﷺ em Meca."),
"sira_119": ("Que fonte brotou para Hajar e o seu filho Isma'il no vale de Meca?", ["Zamzam", "O Nilo", "O Eufrates", "O Jordão"], "Um anjo bateu no chão e brotou a água de Zamzam; Hajar fez uma bacia em seu redor."),
"sira_120": ("O que estava gravado no anel do Profeta ﷺ?", ["«Muhammad Rasul Allah»", "«Allahu Akbar»", "«La ilaha illa Allah»", "Apenas o seu nome"], "O seu anel de prata tinha «Muhammad, Mensageiro de Allah» em três linhas."),
"sira_121": ("De que alimentos gostava o Profeta ﷺ, segundo Aisha?", ["Doces e mel", "Peixe", "Especiarias fortes", "Apenas vinagre"], "Aisha relata que o Profeta ﷺ amava as coisas doces e o mel."),
"sira_122": ("Em que dia da semana nasceu o Profeta ﷺ, dia em que também jejuava?", ["Segunda-feira", "Sexta-feira", "Sábado", "Quarta-feira"], "Questionado sobre o jejum à segunda-feira, disse: «É o dia em que nasci e o dia em que me chegou a revelação»."),
"sira_123": ("Onde estava o «selo da profecia» no corpo do Profeta ﷺ?", ["Entre os ombros", "Na mão", "Na testa", "No peito"], "O selo da profecia estava entre os seus ombros."),
"sira_124": ("De que madeira fez um carpinteiro o minbar (púlpito) do Profeta ﷺ?", ["Tamargueira (athl)", "Cedro", "Oliveira", "Palmeira"], "O Profeta ﷺ mandou fazer um minbar de madeira de tamargueira, de onde se dirigia às pessoas."),
"sira_125": ("Que duas grandes tribos de Medina formaram os Ansar?", ["Os Aws e os Khazraj", "Quraysh e Thaqif", "Tamim e Hawazin", "Kinda e Hamdan"], "Os Aws e os Khazraj, rivais de longa data, uniram-se no islão e tornaram-se os Ansar."),
"sira_126": ("Que título dá o Alcorão às esposas do Profeta ﷺ?", ["As Mães dos Crentes", "As rainhas de Medina", "As filhas de Quraysh", "As guardiãs do Livro"], "«As suas esposas são as suas mães»: as Mães dos Crentes."),
"sira_127": ("Em que ano do calendário cristão ocorreu a Hégira?", ["622", "570", "632", "610"], "A Hégira, em 622, marca o início do calendário muçulmano."),
"sira_128": ("O que respondeu Abd ar-Rahman ibn Awf quando o seu irmão ansari lhe ofereceu metade dos seus bens?", ["«Mostra-me o mercado»", "Aceitou tudo", "Pediu uma casa", "Recusou-se a falar"], "Disse: «Que Allah abençoe os teus bens e a tua família; mostra-me apenas o mercado», e prosperou no comércio."),
"sira_129": ("A que companheiro perguntou o Profeta ﷺ qual é o maior versículo do Alcorão, antes de o felicitar pela resposta (o Versículo do Trono)?", ["Ubayy ibn Ka'b", "Abu Bakr", "Zayd ibn Thabit", "Bilal"], "Ubayy respondeu: «Allah, não há deus senão Ele, o Vivente…»; o Profeta ﷺ disse: «Que o conhecimento te alegre, Abu al-Mundhir!»."),
"sira_130": ("Como foi escolhido o local da mesquita do Profeta ﷺ em Medina?", ["Onde a sua camela se ajoelhou", "Tirando à sorte", "No centro do mercado", "No monte Uhud"], "Deixou a camela andar livremente: onde ela se ajoelhou, construiu-se a mesquita."),
"sira_131": ("Quantos filhos varões teve o Profeta ﷺ, todos falecidos em criança?", ["Três", "Um", "Cinco", "Nenhum"], "Al-Qasim e Abdullah, filhos de Khadija, e Ibrahim, nascido em Medina."),
"sira_132": ("Que companheiro, libertado pelo Profeta ﷺ e criado como um filho, foi o pai de Usama?", ["Zayd ibn Haritha", "Bilal", "Salman", "Ammar"], "Zayd ibn Haritha, amado do Profeta ﷺ, foi o pai de Usama ibn Zayd."),
"sira_133": ("Que jovem companheiro nomeou o Profeta ﷺ para comandar um exército pouco antes da sua morte, apesar da sua juventude?", ["Usama ibn Zayd", "Anas ibn Malik", "Ibn Abbas", "Ibn Umar"], "O Profeta ﷺ deu o comando a Usama e respondeu aos que criticavam a sua idade que ele era digno dele, como o seu pai."),
"sira_134": ("Que avô do Profeta ﷺ voltou a escavar o poço de Zamzam, entulhado havia muito?", ["Abd al-Muttalib", "Hashim", "Abd Manaf", "Qusayy"], "Abd al-Muttalib voltou a escavar Zamzam e encarregou-se dele para os peregrinos."),
"sira_135": ("Quantas pessoas, aproximadamente, acompanharam o Profeta ﷺ na batalha de Badr?", ["Pouco mais de trezentas", "Dez mil", "Mil", "Cinquenta"], "Os muçulmanos em Badr eram pouco mais de trezentos, face a um exército muito maior."),
"sira_136": ("Em que mês do calendário muçulmano nasceu o Profeta ﷺ?", ["Rabi' al-Awwal", "Ramadão", "Muharram", "Dhul-Hijja"], "Nasceu no mês de Rabi' al-Awwal, no Ano do Elefante."),
"sira_137": ("Em que mês chegou o Profeta ﷺ a Medina durante a Hégira?", ["Rabi' al-Awwal", "Ramadão", "Muharram", "Rajab"], "Chegou a Medina em Rabi' al-Awwal, depois de parar em Quba."),
"sira_138": ("Que pacto fizeram os Quraysh para isolar os Banu Hashim, que protegiam o Profeta ﷺ?", ["Um boicote: sem comércio nem casamentos com eles", "Uma trégua de dez anos", "Uma partilha da Ka'ba", "Uma aliança militar"], "Os Quraysh assinaram um pacto de boicote, e os Banu Hashim ficaram confinados a um vale durante anos."),
"sira_139": ("Como começou o Profeta ﷺ a sua missão em Meca, antes da chamada pública?", ["Chamando discretamente o seu círculo próximo", "Com um exército", "Com uma carta aos reis", "Com uma peregrinação"], "Primeiro chamou em privado os seus parentes e amigos, antes de a chamada se tornar pública."),
"sira_140": ("Entre que duas colinas correu Hajar à procura de água para Isma'il?", ["As-Safa e Al-Marwa", "Uhud e Thawr", "Arafat e Mina", "Hira e Thawr"], "Correu sete vezes entre as-Safa e al-Marwa: a origem do sa'y dos peregrinos."),
"sira_141": ("De que neto disse o Profeta ﷺ: «Este meu filho é um sayyid; Allah reconciliará por ele dois grupos de muçulmanos»?", ["Al-Hasan", "Al-Husayn", "Usama", "Ibn Abbas"], "Al-Hasan ibn Ali reconciliou mais tarde dois grandes grupos de muçulmanos, como o Profeta ﷺ tinha anunciado."),
"sira_142": ("Como se chamava a filha do Profeta ﷺ, mãe de Al-Hasan e Al-Husayn?", ["Fátima", "Zaynab", "Ruqayya", "Umm Kulthum"], "Fátima, esposa de Ali, foi a mãe de Al-Hasan e Al-Husayn."),
"sira_143": ("Quem era a filha mais velha do Profeta ﷺ?", ["Zaynab", "Fátima", "Ruqayya", "Umm Kulthum"], "Zaynab era a mais velha das quatro filhas do Profeta ﷺ."),
"sira_144": ("Que companheiro, antigo escravo de origem abissínia, foi escolhido muezim pela sua bela voz?", ["Bilal ibn Rabah", "Salman", "Suhayb", "Zayd"], "Bilal, libertado por Abu Bakr, tornou-se o muezim do Profeta ﷺ."),
"sira_145": ("De que companheiro disse o Profeta ﷺ: «Se tomasse um amigo íntimo (khalil) entre os homens, seria ele»?", ["Abu Bakr", "Umar", "Ali", "Uthman"], "«Se tomasse um amigo íntimo da minha comunidade, tomaria Abu Bakr, mas ele é meu irmão e companheiro.»"),
"sira_146": ("Que cidade, juntamente com Meca, se chama «al-Haramayn», os dois santuários?", ["Medina", "Jerusalém", "Ta'if", "Damasco"], "Meca e Medina são as duas cidades santas, al-Haramayn."),
"sira_147": ("Quantas vezes fez o Profeta ﷺ o Hajj depois da Hégira?", ["Uma, a Peregrinação de Despedida", "Três vezes", "Todos os anos", "Nunca"], "Fez apenas um Hajj depois da Hégira: a Peregrinação de Despedida, no ano 10."),
"sira_148": ("Segundo Anas, o que fez o Profeta ﷺ quando um beduíno lhe puxou com força o manto exigindo bens?", ["Sorriu e ordenou que lhe dessem algo", "Mandou castigá-lo", "Foi-se embora sem uma palavra", "Expulsou-o"], "O Profeta ﷺ voltou-se para ele, riu-se e ordenou que lhe dessem algo."),
"sira_149": ("Que cidade, onde fica a mesquita al-Aqsa, foi o destino da Viagem Noturna?", ["Jerusalém", "Damasco", "Cairo", "Bagdade"], "A Viagem Noturna levou o Profeta ﷺ de Meca à mesquita al-Aqsa em Jerusalém."),
"sira_150": ("Que idade tinha o Profeta ﷺ quando morreu?", ["Sessenta e três", "Quarenta", "Cinquenta", "Oitenta"], "Morreu aos sessenta e três anos, no ano 11 da Hégira."),
}
